        "COMMIT;",
        RELOAD,
        "DROP TABLE IF EXISTS _ctx;",
    ])

# still pending: keep the latest raw snapshot for support, change nothing else
return "UPDATE payments SET RawJson = " + raw + ", UpdatedAt = CURRENT_TIMESTAMP WHERE Id = " + str(pid) + ";\n" + RELOAD

