        "(SELECT COUNT(*) FROM orders WHERE Status = 'pending') AS PendingOrders, "
        "(SELECT COUNT(*) FROM orders WHERE Status = 'paid' AND FulfillmentStatus = 'unfulfilled') AS AwaitingFulfillment, "
