        "(SELECT COUNT(*) FROM carts WHERE Status = 'open' AND UpdatedAt >= datetime('now','-7 days')) AS OpenCarts7d, "
        "(SELECT Value FROM settings WHERE Key = 'currency') AS Currency;"
    )

if op == 'recent-orders':
