# Contact — validate and store a message from the storefront contact form.
import re as _re
d = body()
if op_of(d, 'send') != 'send':
    fail('Unknown op.')
name = str(d.get('name') or '').strip()[:120]
email = str(d.get('email') or '').strip().lower()
subject = str(d.get('subject') or '').strip()[:200]
message = str(d.get('message') or '').strip()
order_ref = str(d.get('orderReference') or '').strip()[:40]
if not email or len(email) > 200 or not _re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', email):
    fail('Please enter a valid email address.')
if len(message) < 10:
    fail('Please tell us a little more (at least 10 characters).')
if len(message) > 5000:
    fail('Messages are limited to 5000 characters.')
# Honeypot: bots fill every field; humans never see this one.
if str(d.get('website') or '').strip():
    return "SELECT 0 AS Id, " + q(email) + " AS Email, " + qs(subject) + " AS Subject, '' AS Message, '' AS Name, '' AS OrderReference, CURRENT_TIMESTAMP AS CreatedAt;"
uid = idp_user_id('''${IdpAuth}''')
return (
    "INSERT INTO contact_messages (Name, Email, Subject, Message, OrderReference, IdpUserId) VALUES (" + qs(name) + ", " + q(email) + ", " + qs(subject) + ", " + q(message) + ", " + qs(order_ref) + ", " + ('NULL' if uid <= 0 else str(uid)) + ");\n"
    "SELECT Id, Name, Email, Subject, Message, OrderReference, CreatedAt FROM contact_messages WHERE Id = last_insert_rowid();"
)

# ---- shop shared helpers ------------------------------------------------------------
# Prepended to every Function/Condition node script by cloudgate/deploy.py. Cloudgate runs
# each script standalone (CPython via pythonnet) inside a `def main():` wrapper, so nothing
# here can be imported — it is inlined. Keep it small and dependency-free.
#
# Cloudgate substitutes ${key} placeholders as raw text BEFORE the script runs, then doubles
# any \" it finds (PrepLambda). Consequences for these helpers:
#   * never write the two characters backslash+quote in a script; use \x22 in regexes.
#   * JSON pasted into a triple-quoted string arrives with \" intact but \\ collapsed;
#     load_json() repairs that.
import json as _json
import re as _re
import datetime as _dt

def _fix_backslashes(s):
    # Restore any backslash that is not followed by a valid JSON escape character.
    return _re.sub(r'\\(?![\x22\\/bfnrtu])', r'\\\\', s)

def load_json(raw, default=None):
    """Parse text Cloudgate substituted into the script (a request body, a prior node's output)."""
    if raw is None:
        return default
    raw = str(raw).strip()
    if not raw or raw == 'No records found':
        return default
    try:
        return _json.loads(raw, strict=False)
    except Exception:
        try:
            return _json.loads(_fix_backslashes(raw), strict=False)
        except Exception:
            return default

def rows_of(raw):
    """Database node output -> list of row dicts (empty list for 'No records found')."""
    data = load_json(raw, [])
    if isinstance(data, dict):
        return [data]
    return [r for r in (data or []) if isinstance(r, dict)]

def body():
    """The JSON request body as a dict ({} when empty or malformed)."""
    data = load_json("""${body}""", {})
    return data if isinstance(data, dict) else {}

def op_of(d, default):
    return str(d.get('op') or default).strip().lower()

def out(data):
    return _json.dumps(data, ensure_ascii=False, default=str)

def fail(message):
    # A raised exception becomes an HTTP 400 with this message as the body.
    raise Exception(message)

# ---- SQL fragment builders (SQLite). Values are quoted here; never interpolate raw input.
def q(v):
    if v is None:
        return 'NULL'
    return "'" + str(v).replace("'", "''") + "'"

def qs(v, max_len=None, default=None):
    """Quoted trimmed string, NULL when empty."""
    if v is None:
        return 'NULL' if default is None else q(default)
    s = str(v).strip()
    if not s:
        return 'NULL' if default is None else q(default)
    if max_len:
        s = s[:max_len]
    return q(s)

def qi(v, default=None):
    """Integer literal or NULL (or default)."""
    try:
        if v is None or v == '':
            return 'NULL' if default is None else str(int(default))
        return str(int(v))
    except Exception:
        return 'NULL' if default is None else str(int(default))

def qb(v):
    return '1' if v in (True, 1, '1', 'true', 'True', 'yes', 'on') else '0'

def to_int(v, default=0):
    try:
        if v is None or v == '':
            return default
        return int(v)
    except Exception:
        return default

def clamp(v, lo, hi, default):
    n = to_int(v, default)
    return max(lo, min(hi, n))

def like(v):
    """'%term%' ESCAPE clause for LIKE, with wildcards in the term neutralised."""
    s = str(v).replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_').replace("'", "''")
    return "'%" + s + "%' ESCAPE '\\'"

def slugify(s):
    s = _re.sub(r'[^a-z0-9]+', '-', str(s or '').lower()).strip('-')
    return s[:120] or 'item'

def now_sql():
    return _dt.datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')

def cents(v, default=None):
    """Money input -> integer cents. Accepts ints (cents) or strings like '349.00' (major units)."""
    if v is None or v == '':
        return default
    try:
        if isinstance(v, bool):
            return default
        if isinstance(v, int):
            return v
        s = str(v).strip()
        if '.' in s or ',' in s:
            return int(round(float(s.replace(',', '')) * 100))
        return int(s)
    except Exception:
        return default

# ---- identity helpers. Pass the substituted IdP node output in from the script.
def idp_user(raw):
    """IdP Authorize (UserInfo output) -> dict or None for anonymous."""
    u = load_json(raw, None)
    if not isinstance(u, dict):
        return None
    if not (u.get('Id') or u.get('id')) and not u.get('Email'):
        return None
    return u

def idp_user_id(raw):
    try:
        return int(str(raw).strip() or 0)
    except Exception:
        return 0

def require_admin(raw):
    u = idp_user(raw)
    if not u:
        fail('Sign in required.')
    if str(u.get('Role') or '').strip().lower() not in ('admin', 'administrator', 'owner'):
        fail('Admin role required.')
    if u.get('IsActive') is False:
        fail('Account disabled.')
    return u

# ---- node script ----
# Shared / SendEmail — deliver the message composed by the previous node (OrderEmail) over SMTP.
# The shop admin configures the mail server under Back office -> Settings -> Email; the values arrive
# here through ${EmailSettings} (settings rows). Nothing is sent, and nothing fails, until that is done:
# the customer-facing flow never depends on email. Returns {sent, reason?, to?, reference?}.
import smtplib as _smtp
import ssl as _ssl
from email.message import EmailMessage as _EmailMessage
from email.utils import formataddr as _formataddr, make_msgid as _make_msgid

msg = load_json('''${OrderEmail}''', None)
if not isinstance(msg, dict) or not msg.get('to'):
    return out({'sent': False, 'reason': 'nothing to send'})

settings = {r.get('Key'): (r.get('Value') or '') for r in rows_of('''${EmailSettings}''')}
host = str(settings.get('smtp_host') or '').strip()
port = to_int(settings.get('smtp_port'), 0)
security = str(settings.get('smtp_security') or 'starttls').strip().lower()
username = str(settings.get('smtp_user') or '').strip()
password = str(settings.get('smtp_password') or '')
from_email = str(settings.get('smtp_from_email') or settings.get('support_email') or msg.get('from') or '').strip()
from_name = str(settings.get('smtp_from_name') or msg.get('fromName') or settings.get('store_name') or '').strip()

if not host:
    return out({'sent': False, 'reason': 'Email is not set up yet. Add your SMTP server under Settings > Email.', 'to': msg.get('to'), 'reference': msg.get('reference')})
if not from_email:
    return out({'sent': False, 'reason': 'No sender address: set a From email under Settings > Email (or a support email).', 'to': msg.get('to'), 'reference': msg.get('reference')})
if port <= 0:
    port = 465 if security == 'ssl' else 587

mail = _EmailMessage()
mail['Subject'] = str(msg.get('subject') or '(no subject)')
mail['From'] = _formataddr((from_name, from_email)) if from_name else from_email
mail['To'] = str(msg.get('to'))
mail['Message-ID'] = _make_msgid(domain=from_email.split('@')[-1] or None)
if msg.get('replyTo'):
    mail['Reply-To'] = str(msg.get('replyTo'))
mail.set_content(str(msg.get('text') or ''))
if msg.get('html'):
    mail.add_alternative(str(msg.get('html')), subtype='html')

try:
    context = _ssl.create_default_context()
    if security == 'ssl':
        server = _smtp.SMTP_SSL(host, port, timeout=20, context=context)
    else:
        server = _smtp.SMTP(host, port, timeout=20)
    with server:
        server.ehlo()
        if security == 'starttls':
            server.starttls(context=context)
            server.ehlo()
        if username:
            server.login(username, password)
        server.send_message(mail)
    return out({'sent': True, 'to': msg.get('to'), 'reference': msg.get('reference'), 'via': host + ':' + str(port)})
except _smtp.SMTPAuthenticationError as ex:
    return out({'sent': False, 'reason': 'The mail server rejected the username or password (' + str(ex.smtp_code) + ').', 'to': msg.get('to'), 'reference': msg.get('reference')})
except _smtp.SMTPRecipientsRefused:
    return out({'sent': False, 'reason': 'The mail server refused the recipient address ' + str(msg.get('to')) + '.', 'to': msg.get('to'), 'reference': msg.get('reference')})
except Exception as ex:
    return out({'sent': False, 'reason': ('Could not send through ' + host + ':' + str(port) + ' - ' + str(ex))[:300], 'to': msg.get('to'), 'reference': msg.get('reference')})

